// Merge taxonomy species into the main flowers array (skip duplicates by latin name)
(function() {
  const existingLatins = new Set(flowers.map(f => f.latin));
  TAXONOMY_FLOWERS.forEach(f => {
    if (!existingLatins.has(f.latin)) flowers.push(f);
  });
})();

